// MeFlex offline support (Stage 25). GENERATED by app/build.py from app/sw.template.js: do not edit meflex-site/sw.js.
// VERSION is a hash of the site's own files, so it changes automatically whenever any of them changes.
// What this does: keeps a copy of the app's own files (FILES) so the app opens without a signal, and serves those files
// from that copy. It never touches any other request (analytics, fonts, anything on another site or outside its folder):
// those go to the network exactly as without it. It sends nothing of its own except fetching FILES from the site.
// It never stores personal data: history, routines, settings and answers live in the page's own storage, not here.
// A new version waits until the person taps Reload ("A new version is ready"); it never takes over by itself.
const VERSION = 'b801cdf19cd9';
const PREFIX = 'meflex-offline-';
const CACHE = PREFIX + VERSION;
const FILES = ["index.html", "manifest.webmanifest", "apple-touch-icon.png", "icon-192.png", "icon-512.png"];
const BASE = self.registration.scope; // the folder sw.js lives in, e.g. https://example.github.io/meflex/meflex-site/meflex-site/

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // cache: 'reload' skips the browser's HTTP cache, so the copy matches this version, not an older download.
    await cache.addAll(FILES.map(f => new Request(BASE + f, { cache: 'reload' })));
    // Safety: the page must be the one built with this sw.js (a half-finished upload is not kept).
    const page = await (await cache.match(BASE + 'index.html')).text();
    if (!page.includes(VERSION)) { await caches.delete(CACHE); throw new Error('MeFlex: page and sw.js are from different versions'); }
  })());
});

self.addEventListener('activate', (e) => {
  // Remove only MeFlex's own older copies; other sites' caches on the same address are never touched.
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith(PREFIX) && k !== CACHE).map(k => caches.delete(k)))));
});

// The page asks for this only when the person taps Reload.
self.addEventListener('message', (e) => { if (e.data === 'meflex-use-new-version') self.skipWaiting(); });

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin || !url.href.startsWith(BASE)) return;
  const rest = url.pathname.slice(new URL(BASE).pathname.length);
  const file = rest === '' ? 'index.html' : rest; // the folder address is the page itself (any ?query is ignored)
  if (!FILES.includes(file)) return;               // anything else: straight to the network, untouched
  e.respondWith(caches.open(CACHE).then(c => c.match(BASE + file)).then(hit => hit || fetch(req)));
});
